-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): mapping.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/mapping.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- INTERMEDIATE
--   iso_live re-graded the Associate tier's live node count (201), which the
--   isochore inherits unchanged, so a learner carried the beginner answer across
--   without gridding. It is replaced by a count only the isochore produces, read
--   in the same panel state: the live isochore nodes above the mean of the six
--   well thicknesses, 146 of 201 at the 100 m capstone cell.
--   RE-KEY iso_live (expected 201, tol 0)
--       -> iso_nodes_above_well_mean 'Live isochore nodes above the well mean' count, expected 146.0, tol 0.0
--   PROMPT was: the thickness at prospect P-1, the live node count, and the
--   plain mean of the six well thicknesses for comparison.
--   PROMPT now: the thickness at prospect P-1, how many live isochore nodes sit
--   above the plain mean of the six well thicknesses, and that plain mean itself
--   for comparison.
--
-- ADVANCED
--   live_with_e7 was 201 a third time: Ekene-7 is interior to the six-well hull,
--   so the live count is unchanged and "unchanged" was the obvious guess. It is
--   replaced by the depth at prospect P-1 on the seven-well grid, read from the
--   Validation explorer's Depth at P-1 tile (4 dp) in the Six plus Ekene-7
--   state: 1547.105224609375 m. tol 0.01 (the annotation proposed 0.1, which the
--   drop-Ekene-4 jackknife reading 1547.2102, 0.105 away, only just clears).
--   RE-KEY live_with_e7 (expected 201, tol 0)
--       -> depth_at_p1_with_e7_m 'Depth at prospect P-1 with Ekene-7 included' m, expected 1547.105224609375, tol 0.01
--   PROMPT was: its residual, and the crest and live node count after regridding
--   with Ekene-7 included.
--   PROMPT now: its residual, and the crest and the depth at prospect P-1 after
--   regridding with Ekene-7 included.
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves: mapping/intermediate,
-- mapping/advanced. Before it writes, the file counts
-- academy_capstone_attempts on each and REFUSES if any exist, unless D5
-- allowlists that tier with the exact attempt ids (allowlist: empty). Stored
-- scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_idtxt    text;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
  v_s1       text;
begin
  -- mapping / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'mapping' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w1 mapping refused: mapping/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '45d873f193573203d370d5324fde35bf' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_live", "tol": 0, "unit": "count", "label": "Live isochore nodes", "expected": 201}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb then 'old'
              when md5(prompt) = '75cf41e29e7051603053d2fb87bf9474' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb then 'new'
              when md5(prompt) = 'a908fe9a048d40be1e82bcfd451816d3' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'mapping' and tier = 'intermediate' and active;
  if v_s0 = 'other' then
    raise exception 'w1 mapping refused: mapping/intermediate matches neither its published form (prompt md5 45d873f193573203d370d5324fde35bf) nor its W1 form (prompt md5 75cf41e29e7051603053d2fb87bf9474), with the fields this file was generated against';
  end if;

  -- mapping / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'mapping' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 mapping refused: mapping/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '8911e9c216aa23bcc8de4279347fc012' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "live_with_e7", "tol": 0, "unit": "count", "label": "Live nodes with Ekene-7 included", "expected": 201}]'::jsonb then 'old'
              when md5(prompt) = '725fa1ff9551cab456e892f529e76c74' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb then 'new'
              when md5(prompt) = 'a7faf6ea15ea17f1aca6dfc26b2decd3' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'mapping' and tier = 'advanced' and active;
  if v_s1 = 'other' then
    raise exception 'w1 mapping refused: mapping/advanced matches neither its published form (prompt md5 8911e9c216aa23bcc8de4279347fc012) nor its W1 form (prompt md5 725fa1ff9551cab456e892f529e76c74), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' and v_s1 = 'new' then
    raise notice 'w1 mapping: 0 of 2 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 mapping refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'mapping' and a.tier = 'intermediate';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'mapping/intermediate' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'mapping/intermediate') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 mapping refused: mapping/intermediate holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 mapping: mapping/intermediate holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 mapping refused: mapping/intermediate holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;
  if v_s1 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'mapping' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'mapping/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'mapping/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_extra) x;
          raise exception 'w1 mapping refused: mapping/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_idtxt;
        end if;
        raise notice 'w1 mapping: mapping/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        select string_agg(x #>> '{}', ', ') into v_idtxt from jsonb_array_elements(v_ids) x;
        raise exception 'w1 mapping refused: mapping/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_idtxt;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Grid both SAND surfaces at the capstone settings and subtract them into an isochore. Read the panel: the thickness extremes and mean, the thickness at prospect P-1, how many live isochore nodes sit above the plain mean of the six well thicknesses, and that plain mean itself for comparison.',
           fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb
     where app_slug = 'mapping' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 mapping refused: mapping/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '75cf41e29e7051603053d2fb87bf9474' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb)
        or (md5(prompt) = 'a908fe9a048d40be1e82bcfd451816d3' and fields = '[{"key": "iso_min_m", "tol": 0.1, "unit": "m", "label": "Isochore minimum thickness", "expected": 25}, {"key": "iso_max_m", "tol": 0.1, "unit": "m", "label": "Isochore maximum thickness", "expected": 35.897705078125}, {"key": "iso_mean_m", "tol": 0.1, "unit": "m", "label": "Isochore mean thickness", "expected": 32.25429068038713}, {"key": "iso_at_p1_m", "tol": 0.1, "unit": "m", "label": "Thickness at prospect P-1", "expected": 34.050048828125}, {"key": "iso_nodes_above_well_mean", "tol": 0.0, "unit": "count", "label": "Live isochore nodes above the well mean", "expected": 146.0}, {"key": "mean_well_thickness_m", "tol": 0.05, "unit": "m", "label": "Mean of the six well thicknesses", "expected": 31.166666666666668}]'::jsonb) from public.academy_capstones where app_slug = 'mapping' and tier = 'intermediate' and active) is not true then
    raise exception 'w1 mapping refused: mapping/intermediate does not read back as its W1 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'Cross-validate the TOP_SAND grid by leave-one-out: only wells INSIDE the control hull can be validated (the gridder masks to the hull, so a removed edge well can never see a prediction at its own location). Report how many wells that is and the residual at Ekene-6. Then blind-test the new appraisal well Ekene-7 at (1500, 1500), actual pick 1549 m: the six-well grid prediction there, its residual, and the crest and the depth at prospect P-1 after regridding with Ekene-7 included.',
           fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb
     where app_slug = 'mapping' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 mapping refused: mapping/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '725fa1ff9551cab456e892f529e76c74' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb)
        or (md5(prompt) = 'a7faf6ea15ea17f1aca6dfc26b2decd3' and fields = '[{"key": "cross_validatable_wells", "tol": 0, "unit": "count", "label": "Wells that can be cross-validated", "expected": 1}, {"key": "loo_resid_e6", "tol": 0.1, "unit": "m", "label": "Leave-one-out residual at Ekene-6", "expected": 9.8438720703125}, {"key": "pred_at_e7", "tol": 0.1, "unit": "m", "label": "Six-well grid prediction at Ekene-7", "expected": 1543.3271484375}, {"key": "blind_residual_e7", "tol": 0.1, "unit": "m", "label": "Blind-test residual at Ekene-7", "expected": -5.6728515625}, {"key": "zmin_with_e7", "tol": 0.1, "unit": "m", "label": "Crest depth with Ekene-7 included", "expected": 1540.70556640625}, {"key": "depth_at_p1_with_e7_m", "tol": 0.01, "unit": "m", "label": "Depth at prospect P-1 with Ekene-7 included", "expected": 1547.105224609375}]'::jsonb) from public.academy_capstones where app_slug = 'mapping' and tier = 'advanced' and active) is not true then
    raise exception 'w1 mapping refused: mapping/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 mapping: % of 2 row(s) written, % already applied', v_written, 2 - v_written;
end $$;
